(function(root){'use strict';const N=typeof module!=='undefined'?require('./normal_sales.js'):root.NormalSales,R=typeof module!=='undefined'?require('./replenishment.js'):root.RYReplenish;function clean(r){N.replay(r.file,r.events);const out={file:r.file,events:r.events};for(const k of ['receivedAt','exportedAt','closedBy','closedAt','issuedFrom','manual','noticeCountedIds'])if(r[k]!==undefined)out[k]=r[k];return out;}function reconcile(a,b){if(JSON.stringify(a.file)!==JSON.stringify(b.file))throw Error('担当指示が一致しません');N.replay(a.file,a.events);N.replay(b.file,b.events);const work=r=>r.events.filter(e=>!['csv','policy'].includes(e.op)).map(e=>{const x={...e};delete x.id;return x;});const x=work(a),y=work(b),short=x.length<y.length?x:y,long=x.length<y.length?y:x;if(!short.every((e,i)=>JSON.stringify(e)===JSON.stringify(long[i])))throw Error('実施記録が分岐しています。履歴は上書きしていません');return y.length>=x.length?b:a;}
function merge(current,incoming){const next=JSON.parse(JSON.stringify(current));for(const [id,value]of Object.entries(incoming)){const r=clean(value);if(id!==r.file.receiptId)throw Error('受付番号が不一致です');const old=next[id];if(old){if(JSON.stringify(old.file)!==JSON.stringify(r.file))throw Error('指示が競合しています');const a=old.events,b=r.events,short=a.length<b.length?a:b,long=a.length<b.length?b:a;if(!short.every((e,i)=>JSON.stringify(e)===JSON.stringify(long[i])))throw Error('作業履歴が競合しています');next[id]=a.length>b.length?old:{...old,...r};}else next[id]=r;}let all=next;for(const r of Object.values(next))all=R.linkReceipt(all,r.file,r);return all;}function pack(records){const out={};for(const [id,r]of Object.entries(records))out[id]=clean(r);return{format:'ry-owner-bundle-v1',savedAt:new Date().toISOString(),records:out};}const api={merge,pack,reconcile};if(typeof module!=='undefined')module.exports=api;else root.OwnerBundle=api;})(globalThis);
